SP="/c/Users/rahul/AppData/Local/Temp/claude/D--DETechAssessment/10853dc6-bb12-440e-95c7-b4d4966ddb77/scratchpad" && cat > "$SP/probe2.py" <<'EOF'
import csv, re, collections
from datetime import date
rows=[]
for p in ["instructions/applications_dataset_1.csv","instructions/applications_dataset_2.csv"]:
    with open(p,newline='',encoding='utf-8') as f: rows+=list(csv.DictReader(f))
print("=== all 4-part names ===")
for r in rows:
    if len(r["name"].split())==4: print("  ", r["name"])
SAL={"mr.","mrs.","ms.","miss","dr.","prof."}
SUF={"md","dds","dvm","phd","jr.","sr.","iii","ii","iv","v"}
left=collections.Counter()
for r in rows:
    p=r["name"].split()
    if p and p[0].lower() in SAL: p=p[1:]
    if len(p)>1 and p[-1].lower() in SUF: p=p[:-1]
    left[len(p)]+=1
print("token count AFTER stripping salutation+suffix:", dict(left))
print("residual 3+:", [r['name'] for r in rows if (lambda p:(len(p[1:] if p and p[0].lower() in SAL else p)-(1 if len(p)>1 and p[-1].lower() in SUF else 0))>2)(r['name'].split())][:20])

# verify age>18 <=> birthday <= 2003-01-01, and the general age expr
def parse(d):
    d=d.strip()
    for f,o in [(r"^(\d{4})[-/](\d{2})[-/](\d{2})$","ymd"),(r"^(\d{2})/(\d{2})/(\d{4})$","mdy"),(r"^(\d{2})-(\d{2})-(\d{4})$","dmy")]:
        m=re.match(f,d)
        if m:
            a,b,c=m.groups(); y,mo,da=(a,b,c) if o=="ymd" else ((c,a,b) if o=="mdy" else (c,b,a))
            try: return date(int(y),int(mo),int(da))
            except ValueError: return None
REF=date(2022,1,1)
def age_py(b): return REF.year-b.year-((b.month,b.day)>(REF.month,REF.day))
def age_expr_sim(b):
    before = (b.month<REF.month) or (b.month==REF.month and b.day<=REF.day)
    return (REF.year-b.year) - (0 if before else 1)
bads=0; thr=0; n=0
for r in rows:
    b=parse(r["date_of_birth"])
    if not b: continue
    n+=1
    if age_py(b)!=age_expr_sim(b): bads+=1
    if (age_py(b)>18) != (b<=date(2003,1,1)): thr+=1
print(f"parsed={n} expr_mismatch={bads} threshold_mismatch={thr}")
for t in ["2003-01-01","2003-01-02","2004-02-29","2002-12-31"]:
    y,m,d=map(int,t.split("-")); b=date(y,m,d)
    print(f"  {t}: age={age_py(b)} expr={age_expr_sim(b)} above_18={age_py(b)>18}")
EOF
PYTHONIOENCODING=utf-8 .venv/Scripts/python.exe "$SP/probe2.py"

